INSERT INTO roles (role_code, role_name, description) VALUES ('ADMIN', 'Administrator', 'Full access: all facilities, user accounts, roles, audit history and system settings.');
INSERT INTO roles (role_code, role_name, description) VALUES ('MANAGER', 'Operations Manager', 'Runs assigned facilities: plans and assigns work, monitors operations and reviews the activity history of their sites.');
INSERT INTO roles (role_code, role_name, description) VALUES ('OPERATOR', 'Operator', 'Floor staff: sees their own facility and works through the tasks assigned to them.');
INSERT INTO permissions (perm_code, description) VALUES ('VIEW_DASHBOARD', 'View the live operations dashboard');
INSERT INTO permissions (perm_code, description) VALUES ('VIEW_ALL_FACILITIES', 'Access every facility regardless of assignment');
INSERT INTO permissions (perm_code, description) VALUES ('MANAGE_USERS', 'Create, edit, deactivate users and grant facility access');
INSERT INTO permissions (perm_code, description) VALUES ('VIEW_AUDIT', 'Read the audit history of changes');
INSERT INTO permissions (perm_code, description) VALUES ('MANAGE_TASKS', 'Create, assign, re-assign and cancel tasks');
INSERT INTO permissions (perm_code, description) VALUES ('UPDATE_OWN_TASKS', 'Start, block and complete tasks assigned to oneself');
INSERT INTO permissions (perm_code, description) VALUES ('CONTROL_SIMULATION', 'Pause, resume and change the speed of live operations');
INSERT INTO permissions (perm_code, description) VALUES ('VIEW_REPORTS', 'View SQL reports and KPIs across facilities');
INSERT INTO permissions (perm_code, description) VALUES ('VIEW_TEAM', 'View staff, job roles and workload');
INSERT INTO permissions (perm_code, description) VALUES ('MANAGE_PARK', 'Edit park tenants: building status, staff numbers and leases');
INSERT INTO permissions (perm_code, description) VALUES ('VIEW_DATABASE', 'Browse the Oracle schema: tables, columns, constraints, row counts');
INSERT INTO permissions (perm_code, description) VALUES ('RUN_SQL', 'Run read-only SQL queries against the Oracle database');
INSERT INTO permissions (perm_code, description) VALUES ('MANAGE_PORT', 'Container terminal: hold or release ships, open or close berths');
INSERT INTO permissions (perm_code, description) VALUES ('MANAGE_RETAIL', 'Vendor stores: place and cancel restock orders on the warehouses');
