INSERT INTO job_titles (job_code, title, responsibilities) VALUES ('SYS_ADMIN', 'System Administrator', 'Manages user accounts, roles and facility access; reviews the full audit trail.');
INSERT INTO job_titles (job_code, title, responsibilities) VALUES ('OPS_MANAGER', 'Operations Manager', 'Plans daily operations, assigns work to staff, monitors docks, inventory and on-time delivery.');
INSERT INTO job_titles (job_code, title, responsibilities) VALUES ('DOCK_SUPERVISOR', 'Dock Supervisor', 'Coordinates truck arrivals, dock bookings, safety checks and loading sequences.');
INSERT INTO job_titles (job_code, title, responsibilities) VALUES ('FORKLIFT_OPERATOR', 'Forklift Operator', 'Loads and unloads trucks, moves pallets between docks, yard slots and storage.');
INSERT INTO job_titles (job_code, title, responsibilities) VALUES ('INVENTORY_CLERK', 'Inventory Clerk', 'Receives goods, performs cycle counts and keeps stock records accurate.');
